ALTER TABLE direction_criterion DROP CONSTRAINT criterion_metric;
ALTER TABLE direction_criterion ADD CONSTRAINT criterion_metric CHECK (metric IN ('MANUAL','WORK_SOURCE_INCOME','BUSINESS_RECEIPTS','NEW_RECURRING_COMPANY','CONVERSATIONS','CONVERSATION_COMPANIES','SESSION_TIME','ENGINEERING_EVIDENCE','SAVINGS_GOAL','CONTENT_CREATED','CONTENT_VARIANTS_CREATED','CONTENT_PUBLICATIONS'));
ALTER TABLE direction_criterion ADD CONSTRAINT criterion_content_scope CHECK (
 (NOT "selectedContentOnly" OR ("experimentId" IS NOT NULL AND metric IN ('CONTENT_CREATED','CONTENT_VARIANTS_CREATED','CONTENT_PUBLICATIONS','SESSION_TIME'))) AND
 ("contentId" IS NULL OR metric IN ('CONTENT_CREATED','CONTENT_VARIANTS_CREATED','CONTENT_PUBLICATIONS','SESSION_TIME')) AND
 ("channelId" IS NULL OR metric='CONTENT_PUBLICATIONS') AND
 ("contentFormat" IS NULL OR ("contentFormat" IN ('LONG_FORM','SHORT_VERTICAL','OTHER') AND metric IN ('CONTENT_VARIANTS_CREATED','CONTENT_PUBLICATIONS'))));
